CREATE     PROCEDURE [synapse_fo].[usp_Insert_CUSTPAYMMODETABLE]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:29:41
	Description: Insert stored procedure for CUSTPAYMMODETABLE from synapse finops datalake to BI
*/
BEGIN
	INSERT INTO [synapse_fo].[CUSTPAYMMODETABLE]
	(
		[ACCOUNTTYPE],
		[BANKCLIENTCLASSID_RU],
		[BANKCLIENTDOCUMENTTYPEID_RU],
		[BANKCUSTPAYMIDTABLE],
		[BANKTRANSTYPE],
		[CATEGORYPURPOSE_W],
		[CHARGEBEARER_W],
		[CLASSID],
		[CLASSIDFILEANALYZE],
		[CLASSIDIN],
		[CLASSIDREMITTANCE],
		[CLASSIDRETURN],
		[DATAAREAID],
		[DataLakeModified_DateTime],
		[DESCPRIMARYMETHOD_BR],
		[DIMCTRL],
		[DIMENSIONATTRIBUTESET],
		--[DIMUSE],
		--[DIMUSE2_],
		--[DIMUSE3_],
		[DIRECTDEBIT],
		[DISCGRACEDAYS],
		[ERFORMATMAPPINGID],
		[ERMODELMAPPINGTABLE],
		[EXPORTLAYOUTGROUPID_BR],
		[EXPORTONINVOICE],
		--[FileName],
		[FURTHERPOSTING],
		[INTERCOMPANYLEDGERDIMENSION],
		[ISSEPA],
		[LastProcessedChange_DateTime],
		[LASTSEQUENCENUMBER],
		[LASTSEQUENCENUMDATE],
		[LASTSEQUENCENUMTODAY],
		[LOCALINSTRUMENT_W],
		--[LSN],
		[NAME],
		[NUMBERSEQUENCETABLE_LT],
		[PARTITION],
		[PAYMENTLEDGERDIMENSION],
		[PAYMENTMETHOD_BR],
		[PAYMENTTYPE],
		[PAYMENTTYPE_MX],
		[PAYMJOURNALNAMEID],
		[PAYMMODE],
		[PAYMONINVOICE],
		[PAYMSTATUS],
		[PAYMSUMBY],
		[PDCCLEARINGPOSTING],
		[POSTINGPROFILEBILLSREMITCOLLECTION_IT],
		[POSTINGPROFILEBILLSREMITDISCOUNT_IT],
		[PRIMARYMETHOD_BR],
		[RECID],
		[RECVERSION],
		[RETURNLAYOUTGROUPID_BR],
		[SERVICELEVEL_W],
		--[SKS_CNP_FORMATID],
		--[SKS_CNP_PAYMMODE],
		--[SKS_EFT_FORMATID],
		--[SKS_EFT_PAYMMODE],
		[SPLITPAYMENT_W],
		--[SysRowId],
		[TYPEOFDRAFT],
		[USECUSTOMFORMAT_RU],
		[USEGERCONFIGURATION],
		[USEGERIMPORT]
	)
	SELECT 
		stg.[ACCOUNTTYPE],
		stg.[BANKCLIENTCLASSID_RU],
		stg.[BANKCLIENTDOCUMENTTYPEID_RU],
		stg.[BANKCUSTPAYMIDTABLE],
		stg.[BANKTRANSTYPE],
		stg.[CATEGORYPURPOSE_W],
		stg.[CHARGEBEARER_W],
		stg.[CLASSID],
		stg.[CLASSIDFILEANALYZE],
		stg.[CLASSIDIN],
		stg.[CLASSIDREMITTANCE],
		stg.[CLASSIDRETURN],
		stg.[DATAAREAID],
		stg.[DataLakeModified_DateTime],
		stg.[DESCPRIMARYMETHOD_BR],
		stg.[DIMCTRL],
		stg.[DIMENSIONATTRIBUTESET],
		--stg.[DIMUSE],
		--stg.[DIMUSE2_],
		--stg.[DIMUSE3_],
		stg.[DIRECTDEBIT],
		stg.[DISCGRACEDAYS],
		stg.[ERFORMATMAPPINGID],
		stg.[ERMODELMAPPINGTABLE],
		stg.[EXPORTLAYOUTGROUPID_BR],
		stg.[EXPORTONINVOICE],
		--stg.--[FileName],
		stg.[FURTHERPOSTING],
		stg.[INTERCOMPANYLEDGERDIMENSION],
		stg.[ISSEPA],
		stg.[LastProcessedChange_DateTime],
		stg.[LASTSEQUENCENUMBER],
		stg.[LASTSEQUENCENUMDATE],
		stg.[LASTSEQUENCENUMTODAY],
		stg.[LOCALINSTRUMENT_W],
		--stg.--[LSN],
		stg.[NAME],
		stg.[NUMBERSEQUENCETABLE_LT],
		stg.[PARTITION],
		stg.[PAYMENTLEDGERDIMENSION],
		stg.[PAYMENTMETHOD_BR],
		stg.[PAYMENTTYPE],
		stg.[PAYMENTTYPE_MX],
		stg.[PAYMJOURNALNAMEID],
		stg.[PAYMMODE],
		stg.[PAYMONINVOICE],
		stg.[PAYMSTATUS],
		stg.[PAYMSUMBY],
		stg.[PDCCLEARINGPOSTING],
		stg.[POSTINGPROFILEBILLSREMITCOLLECTION_IT],
		stg.[POSTINGPROFILEBILLSREMITDISCOUNT_IT],
		stg.[PRIMARYMETHOD_BR],
		stg.[RECID],
		stg.[RECVERSION],
		stg.[RETURNLAYOUTGROUPID_BR],
		stg.[SERVICELEVEL_W],
		--stg.[SKS_CNP_FORMATID],
		--stg.[SKS_CNP_PAYMMODE],
		--stg.[SKS_EFT_FORMATID],
		--stg.[SKS_EFT_PAYMMODE],
		stg.[SPLITPAYMENT_W],
		--stg.--[SysRowId],
		stg.[TYPEOFDRAFT],
		stg.[USECUSTOMFORMAT_RU],
		stg.[USEGERCONFIGURATION],
		stg.[USEGERIMPORT]	
	FROM [staging_fo].[CUSTPAYMMODETABLE] stg
		LEFT JOIN [synapse_fo].[CUSTPAYMMODETABLE] tgt
			ON stg.[DataAreaId] = tgt.[DataAreaId] 
			AND stg.[PARTITION] = tgt.[PARTITION] 
			AND stg.[PaymMode] = tgt.[PaymMode] 
		
	WHERE tgt.[RECID] IS NULL
END
